#include <stdio.h>

int main(void) {
    unsigned long long n;
    unsigned int p;
    if (scanf("%llu %u", &n, &p) != 2) {
        return 1;
    }
    unsigned long long mask = 1ULL << p;
    unsigned long long full = 0xFFFFFFFFULL;
    printf("%llu\n", (n | mask) & full);
    printf("%llu\n", (n & ~mask) & full);
    printf("%llu\n", (n ^ mask) & full);
    return 0;
}
